response_html:
{% set company_id = company %}
{% set company_info = frappe.db.get_value("Company", company_id, ["company_name", "email", "phone_no", "tax_id", "company_description", "company_logo", "default_bank_account"], as_dict=True) or {} %}
{% set bank_account_name = company_info.get("default_bank_account") %}
{% if not bank_account_name %}
{% set bank_account_names = frappe.db.get_all("Bank Account", filters={"company": company_id, "is_company_account": 1, "is_default": 1}, pluck="name", limit=1) %}
{% if not bank_account_names %}
{% set bank_account_names = frappe.db.get_all("Bank Account", filters={"company": company_id, "is_company_account": 1}, pluck="name", limit=1) %}
{% endif %}
{% set bank_account_name = bank_account_names[0] if bank_account_names else None %}
{% endif %}
{% set bank_account = frappe.db.get_value("Bank Account", bank_account_name, ["bank", "bank_account_no", "iban"], as_dict=True) if bank_account_name else {} %}
{% set bank_account = bank_account or {} %}
{% set bank = frappe.db.get_value("Bank", bank_account.get("bank"), ["bank_name", "swift_number"], as_dict=True) if bank_account.get("bank") else {} %}
{% set bank = bank or {} %}
{% set company_name = company_info.get("company_name") or company_id %}
{% set customer_display = customer_name or customer %}
{% set payment_period = custom_okres_rozliczeniowy if custom_okres_rozliczeniowy is defined else None %}
{% set service_rows = items or [] %}
{% set payment_url = frappe.utils.get_url_to_form(doctype or "Sales Invoice", name) %}

<div style="font-family: Arial, sans-serif; color: #333; line-height: 1.6;">
  <div style="max-width: 600px; margin: 0 auto; padding: 20px;">

    <h2 style="color: #2b6cb0; margin-bottom: 10px;">
      Faktura za usługi {{ name }}
    </h2>

    <p>Dzień dobry {{ customer_display }},</p>

    <p>
      W systemie <b>{{ company_name }}</b> została wystawiona nowa <strong>faktura za usługi nr {{ name }}</strong>.
    </p>

    {% if payment_period %}
    <p>
      Okres rozliczeniowy:
      <strong>{{ payment_period }}</strong>
    </p>
    {% endif %}

    <br>
    <p>
      <strong>Kwota do zapłaty:</strong> {{ grand_total }} {{ currency }}<br>
      <strong>Termin płatności:</strong> {{ due_date or "-" }}<br>
      <strong>Data wystawienia:</strong> {{ posting_date or "-" }}
    </p>

    <p>
      Dokument można otworzyć tutaj:
      <a href="{{ payment_url }}" style="color: #2b6cb0; text-decoration: none; border-bottom: 1px dotted #2b6cb0;">{{ payment_url }}</a>
    </p>

    {% if service_rows %}
    <br>
    <h3 style="color: #2b6cb0;">Pozycje na fakturze:</h3>
    <table cellpadding="8" cellspacing="0" border="0" style="width: 100%; border-collapse: collapse; font-size: 14px;">
      <thead>
        <tr style="background: #f3f4f6;">
          <th align="left" style="border: 1px solid #e5e7eb;">Usługa</th>
          <th align="right" style="border: 1px solid #e5e7eb;">Ilość</th>
          <th align="right" style="border: 1px solid #e5e7eb;">Cena</th>
          <th align="right" style="border: 1px solid #e5e7eb;">Wartość</th>
        </tr>
      </thead>
      <tbody>
        {% for row in service_rows %}
        <tr>
          <td style="border: 1px solid #e5e7eb;">
            {{ row.get("item_name") or row.get("item_code") or "-" }}
            {% if row.get("description") %}
            <div style="font-size: 12px; color: #6b7280; margin-top: 4px;">{{ row.get("description") }}</div>
            {% endif %}
          </td>
          <td align="right" style="border: 1px solid #e5e7eb;">{{ row.get("qty") or "-" }}</td>
          <td align="right" style="border: 1px solid #e5e7eb;">{{ row.get("rate") or "-" }} {{ currency }}</td>
          <td align="right" style="border: 1px solid #e5e7eb;">{{ row.get("amount") or "-" }} {{ currency }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
    {% endif %}

    {% if bank_account_name %}
    <br>
    <h3 style="color: #2b6cb0;">Dane do przelewu:</h3>
    <p>
      <strong>{{ company_name }}</strong><br>
      NIP: {{ company_info.get("tax_id") or "-" }}<br>
      Bank: {{ bank.get("bank_name") or bank_account.get("bank") or "-" }}<br>
      Numer konta: {{ bank_account.get("bank_account_no") or "-" }}<br>
      IBAN: {{ bank_account.get("iban") or "-" }}<br>
      SWIFT: {{ bank.get("swift_number") or "-" }}<br>
      <strong>Tytuł przelewu:</strong> {{ name }}
    </p>
    {% endif %}

    <br>

    <hr style="border: none; border-top: 1px solid #ddd; margin: 30px 0;">

    <div style="padding: 18px 22px; background: #f9fafb; border-top: 1px solid #e5e7eb;">
      <div style="font-size: 14px; font-weight: 800; color: #111827; margin: 0 0 2px 0;">{{ company_name }}</div>
      <div style="font-size: 13px; color: #6b7280; margin: 0 0 12px 0;">{{ company_info.get("company_description") or "Wiadomość wygenerowana automatycznie" }}</div>

      <div style="font-size: 13px; color: #374151; margin: 0 0 8px 0;">
        {% if company_info.get("email") %}
        <span style="display: inline-block; margin-right: 10px;">
          <strong>Email:</strong>
          <a href="mailto:{{ company_info.get('email') }}" style="color: #111827; text-decoration: none; border-bottom: 1px dotted #9ca3af;">{{ company_info.get("email") }}</a>
        </span>
        {% endif %}
        {% if company_info.get("phone_no") %}
        <span style="display: inline-block;">
          <strong>Tel:</strong>
          <a href="tel:{{ company_info.get('phone_no') }}" style="color: #111827; text-decoration: none; border-bottom: 1px dotted #9ca3af;">{{ company_info.get("phone_no") }}</a>
        </span>
        {% endif %}
      </div>

      <div style="font-size: 12px; color: #9ca3af; line-height: 1.5; margin-bottom: 12px;">
        NIP: {{ company_info.get("tax_id") or "-" }}
      </div>

      {% if company_info.get("company_logo") %}
      <img src="{{ company_info.get('company_logo') }}" alt="{{ company_name }}" style="width: 100%; max-width: 320px; height: auto; display: block; margin-top: 6px; border-radius: 12px; border: 1px solid #e5e7eb; background: #ffffff;">
      {% endif %}

      <div style="margin-top: 14px; padding-top: 12px; border-top: 1px solid #e5e7eb; font-size: 12px; color: #9ca3af; line-height: 1.5;">
        Wiadomość została wygenerowana automatycznie - prosimy nie odpowiadać na ten e-mail.
      </div>
    </div>

  </div>
</div>
